# intercept_formula <- as.formula(paste(target, 1, sep = " ~ "))

#' BIEN variable selection for linear regression
#'
#' Performs variable selection using the Bayesian Information Criterion
#' Elastic Net (BIEN) procedure for a continuous outcome.
#'
#' For each value of alpha, BIEN evaluates a sequence of
#' elastic-net penalty parameters (lambda). Each distinct candidate variable set
#' generated by the elastic net is refitted without penalization and scored
#' using the Bayesian information criterion (BIC). The search is stopped after
#' a specified number of consecutive candidate variable sets fail to improve
#' the BIC. The best candidate model is subsequently refined using backward
#' BIC selection.
#' 
#' @param input Character vector containing predictor variable names.
#'   Predictors must be numeric; categorical predictors should be dummy-coded
#'   before calling `bien()`.
#' @param target Character string containing the outcome variable name.
#' @param data A data.frame containing the predictors and outcome.
#' @param alpha_grid Numeric vector of elastic-net alpha values to consider.
#'   Values must lie in (0, 1]. Defaults to seq(0.1, 1, by = 0.1).
#' @param n_lambda Number of lambda values evaluated for each alpha.
#'   Defaults to 1000.
#' @param patience Number of consecutive non-improving variable sets before
#'   stopping the lambda search for a given alpha. Defaults to 5.
#' @param verbose Logical. If TRUE, print progress during model fitting.
#'
#' @return A list containing:
#' \describe{
#'   \item{optimal}{Selected alpha and lambda values.}
#'   \item{model}{Final model.}
#'   \item{grid}{BIC values for all evaluated candidate variable sets.}
#' }
#'
#' @examples
#' \dontrun{
#' fit <- bien(
#'   input = c("x1", "x2", "x3"),
#'   target = "y",
#'   data = dat
#' )
#'
#' fit$model
#' }
#'
#' @export
bien <- function(
    input, 
    target, 
    data, 
    alpha_grid = seq(0.1, 1, by = 0.1),
    n_lambda = 1000,
    patience = 5,
    verbose = FALSE
    ){
  
  # ------------------------------------------------------------------
  # Validate inputs
  # ------------------------------------------------------------------
  
  if (!is.data.frame(data)) {
    stop("`data` must be a data.frame.", call. = FALSE)
  }
  
  if (!is.character(input) || length(input) < 1) {
    stop("`input` must be a character vector of predictor names.",
         call. = FALSE)
  }
  
  if (!is.character(target) || length(target) != 1) {
    stop("`target` must be a single character string.", call. = FALSE)
  }
  
  # Confirm that all requested variables are present in the data.
  missing_vars <- setdiff(c(input, target), names(data))
  
  if (length(missing_vars) > 0) {
    stop(
      "Variables not found in `data`: ",
      paste(missing_vars, collapse = ", "),
      call. = FALSE
    )
  }
  
  # BIEN is currently implemented for continuous numeric outcomes
  if (!is.numeric(data[[target]])) {
    stop("The outcome variable must be numeric.", call. = FALSE)
  }
  
  # Missing values are not currently handled internally.
  if (anyNA(data[, c(input, target), drop = FALSE])) {
    stop(
      "Missing values are not supported in `input` or `target`.",
      call. = FALSE
    )
  }
  
  # glmnet requires a numeric design matrix.
  predictor_numeric <- vapply(
    data[, input, drop = FALSE],
    is.numeric,
    logical(1)
  )
  
  if (!all(predictor_numeric)) { 
    stop(
      "All predictors must currently be numeric.",
      call. = FALSE
    )
  }
  
  if (any(alpha_grid <= 0 | alpha_grid > 1)) {
    stop("`alpha_grid` values must be in the interval (0, 1].",
         call. = FALSE)
  }
  
  if (patience < 1) {
    stop("`patience` must be at least 1.", call. = FALSE)
  }

  # ------------------------------------------------------------------
  # Prepare outcome and predictor matrix
  # ------------------------------------------------------------------
  
  x <- as.matrix(data[, input, drop = FALSE])
  y <- data[[target]]
  
  # Compute population-scale predictor standard deviations.
  predictor_sd <- apply(
    x, 
    2, 
    function (z) sqrt(sum((z-mean(z))^2)/length(z))
    )
  
  if (any(predictor_sd == 0)) {
    stop(
      "Predictors with zero variance are not supported.",
      call. = FALSE
    )
  }
  
  # Standardize predictor matrix.
  sx <- scale(
    x, 
    scale = predictor_sd
  ) 

  # The intercept-only model provides the initial BIC benchmark.
  intercept_formula <- as.formula(paste(target, "~ 1"))
  intercept_model <- glm(
    intercept_formula,
    family = gaussian(),
    data = data
  )
  
  # Store BIC results for all unique candidate variable sets.
  results <- list()
  result_index <- 1L
  
  # ------------------------------------------------------------------
  # Search over alpha and lambda
  # ------------------------------------------------------------------
  for(alpha in alpha_grid){
    
    # Reset the best BIC and stopping rule for each alpha value.
    bic_best <- BIC(intercept_model)
    previous_variables <- character(0)
    patience_count <- 0L
    
    # Determine the largest lambda at which predictors begin to enter
    # the elastic-net model.
    lambda_max <- max(
      abs(colSums(sx*y)), 
      na.rm = TRUE
      ) / (alpha*nrow(x))
    
    # Search down to a small fraction of lambda_max.
    epsilon <- 1e-4
    lambda_min <- lambda_max*epsilon 
    
    # Generate a log-spaced lambda sequence
    lambda_grid <- exp(
      seq(
        log(lambda_max), 
        log(lambda_min), 
        length.out = n_lambda
        )
      )
    
    # Fit the full elastic-net path for the current alpha.
    glmnet_fit <- glmnet::glmnet(
      x = x,
      y = y,
      family = "gaussian",
      alpha = alpha,
      lambda = lambda_grid
    )
    
    # Evaluate candidate variable sets along the lambda path.
    for (j in seq_along(lambda_grid)){
      
      penalized_coef <- glmnet_fit$beta[, j]
      
      # Variables with nonzero penalized coefficients form the
      # current candidate variable set.
      selected_variables <- names(
        penalized_coef[penalized_coef!=0]
        )
      
      # Consecutive lambda values may produce the same selected set.
      # Refit and evaluate only when the variable set changes.
      if(!setequal(selected_variables, previous_variables)){ 
        
        if (length(selected_variables) > 0) {
          
          refit_formula <- reformulate(
            termlabels = selected_variables,
            response = target
          )
          
        } else {
          
          refit_formula <- intercept_formula
        }
        
        # Re-fit an unpenalized model
        refit_model <- glm(
          refit_formula,
          family = gaussian(),
          data = data
        )
        
        current_bic <- BIC(refit_model)
  
        # Store the alpha, lambda, model size, and BIC for this candidate.
        results[[result_index]] <- data.frame(
          alpha = alpha,
          lambda = lambda_grid[j],
          n = length(selected_variables),
          bic = current_bic
        )
        
        result_index <- result_index + 1L
        
        # Reset patience after an improvement; otherwise count another
        # consecutive non-improving candidate set.
        if(current_bic < bic_best){
          (bic_best <- current_bic)
          patience_count <- 0L
          
        } else{
          
          patience_count <- patience_count + 1L
        }
        
        if (verbose) {
          message(
            "alpha = ", alpha,
            "; lambda = ", signif(lambda_grid[j], 5),
            "; #Selected Variables = ", length(selected_variables),
            "; BIC = ", round(current_bic, 3),
            "; best BIC = ", round(bic_best, 3),
            "; #patience = ", patience_count
          )
        }
        
        # Stop searching this alpha after the specified number of
        # consecutive candidate sets fail to improve BIC.
        if(patience_count == patience){
          break
        }
        
        previous_variables <- selected_variables
        }
    }
  }
  grid <- do.call(rbind, results)
  
  # ------------------------------------------------------------------
  # Identify the best alpha and lambda
  # ------------------------------------------------------------------
  best_index <- which.min(grid$bic)
  
  optimal <- grid[
    best_index, 
    c("alpha", "lambda"), 
    drop = FALSE
    ]
  
  # ------------------------------------------------------------------
  # Recover the selected variables at the best alpha and lambda
  # ------------------------------------------------------------------
  
  optimal_fit <- glmnet::glmnet(
    x = x, 
    y = y, 
    family="gaussian", 
    alpha=optimal[1,1], 
    lambda = optimal[1,2]
    )

  optimal_coef <- coef(optimal_fit)[, "s0"][-1]
  
  selected_variables <- names(
    optimal_coef[optimal_coef!=0]
    )
  
  # ------------------------------------------------------------------
  # Refit the selected model without penalization
  # ------------------------------------------------------------------
  
  if (length(selected_variables) > 0) {
    
    refit_formula <- reformulate(
      termlabels = selected_variables,
      response = target
    )
    
  } else {
    
    refit_formula <- intercept_formula
  }
  
  refit_model <- glm(
    refit_formula,
    family = gaussian(),
    data = data
  )

  # ------------------------------------------------------------------
  # Final backward BIC selection
  # ------------------------------------------------------------------
  
  # Starting from the best BIEN candidate, backward elimination removes
  # variables when doing so further improves BIC.
  final_model <- step(
    refit_model,
    direction = "backward",
    k = log(nobs(refit_model)),
    trace = if (verbose) 1 else 0
  )
  
  # ------------------------------------------------------------------
  # Return results
  # ------------------------------------------------------------------
  
  list(optimal = optimal, 
       model = final_model, 
       grid = grid)
}
